-- Telescreen (Robert) fraud review tables. Generated by drizzle-kit, then made idempotent by hand (IF NOT EXISTS):
-- some databases already have these tables from script/migrations/2026-10-telescreen.sql, which created the same
-- objects under the same names before migrations moved to drizzle-kit.
CREATE TABLE IF NOT EXISTS "telescreen_submissions" (
	"id" integer PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "telescreen_submissions_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"projectId" integer NOT NULL,
	"externalId" uuid DEFAULT gen_random_uuid() NOT NULL,
	"robertProjectId" uuid,
	"state" varchar(32) DEFAULT 'unsent' NOT NULL,
	"submittedAt" timestamp,
	"trustScore" integer,
	"reviewNote" varchar(5000),
	"reviewedAt" timestamp,
	"outcomeStatus" varchar(16),
	"outcomeReason" varchar(5000),
	"outcomeAt" timestamp,
	"outcomeBy" varchar(255),
	"outcomeSource" varchar(16),
	"overrideBy" varchar(255),
	"overrideReason" varchar(2000),
	"overrideAt" timestamp,
	"closedAt" timestamp,
	"closeReason" varchar(64),
	"lastError" varchar(1000),
	"createdAt" timestamp DEFAULT now() NOT NULL,
	"updatedAt" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "telescreen_submissions_externalId_unique" UNIQUE("externalId"),
	CONSTRAINT "telescreen_submissions_robertProjectId_unique" UNIQUE("robertProjectId"),
	CONSTRAINT "telescreen_submissions_state_check" CHECK ("telescreen_submissions"."state" IN ('unsent', 'awaiting_review', 'awaiting_outcome', 'rejected_fraud', 'decided', 'withdrawn')),
	CONSTRAINT "telescreen_submissions_trust_score_check" CHECK ("telescreen_submissions"."trustScore" BETWEEN 1 AND 10),
	CONSTRAINT "telescreen_submissions_outcome_status_check" CHECK ("telescreen_submissions"."outcomeStatus" IN ('approved', 'rejected')),
	CONSTRAINT "telescreen_submissions_outcome_source_check" CHECK ("telescreen_submissions"."outcomeSource" IN ('alchemize', 'telescreen'))
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "telescreen_webhook_deliveries" (
	"deliveryId" uuid PRIMARY KEY NOT NULL,
	"event" varchar(32) NOT NULL,
	"robertProjectId" uuid,
	"receivedAt" timestamp DEFAULT now() NOT NULL,
	"processedAt" timestamp
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "telescreen_submissions_one_open" ON "telescreen_submissions" USING btree ("projectId") WHERE "closedAt" IS NULL;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "telescreen_submissions_project" ON "telescreen_submissions" USING btree ("projectId");